import{_ as i,c as n,o as a,a1 as t}from"./chunks/framework.6sy4tsQT.js";const s=JSON.parse('{"title":"Function Calling与MCP","description":null,"frontmatter":{"title":"Function Calling与MCP","description":null,"date":"2026-01-10T00:00:00.000Z","tags":["Function Calling","MCP"]},"headers":[],"relativePath":"ai/function-calling-mcp.md","filePath":"ai/function-calling-mcp.md"}'),o={name:"ai/function-calling-mcp.md"};function c(e,l,u,r,d,g){return a(),n("div",null,[...l[0]||(l[0]=[t('<blockquote><p>Function Calling 与 MCP 的目标：给大模型加上插件</p></blockquote><h2 id="概览" tabindex="-1">概览 <a class="header-anchor" href="#概览" aria-label="Permalink to &quot;概览&quot;">​</a></h2><ul><li>Function Calling - 一个工具箱，一般是自己开发的</li><li>MCP - 一个工具箱，一般是别人开发的</li></ul><h2 id="function-calling" tabindex="-1">Function Calling <a class="header-anchor" href="#function-calling" aria-label="Permalink to &quot;Function Calling&quot;">​</a></h2><ul><li>最早是 Langchain 提出来的，</li><li>后来 OpenAI 也引入了 Function Calling</li></ul><h2 id="function-calling-的作用" tabindex="-1">Function Calling 的作用 <a class="header-anchor" href="#function-calling-的作用" aria-label="Permalink to &quot;Function Calling 的作用&quot;">​</a></h2><ul><li>扩展模型能力 大模型本身无法直接操作外部系统（如数据库、计算工具），但通过调用预设函数，可以完成： 实时数据获取（天气、股价、新闻） 复杂计算（数学运算、代码执行） 操作外部系统（发送邮件、控制智能设备）</li><li>结构化输出 模型可将用户自然语言请求转化为结构化参数，传递给函数。例如： 用户说“明天北京天气如何？” → 模型调用 get_weather(location=&quot;北京&quot;, date=&quot;2025-05-06&quot;)</li><li>动态决策流程 模型可根据上下文决定是否/何时调用函数，甚至链式调用多个函数（如先查天气，再推荐穿搭）。 Function Call是大模型与真实世界交互的“桥梁” ，从语言理解 =&gt; 具体行动</li></ul><h2 id="function-calling-与-mcp-混用" tabindex="-1">Function Calling 与 MCP 混用 <a class="header-anchor" href="#function-calling-与-mcp-混用" aria-label="Permalink to &quot;Function Calling 与 MCP 混用&quot;">​</a></h2><ul><li>对 LLM 来说，Function Calling 是一个工具，MCP 也是一组工具，所以二者混用，没有问题。</li></ul><h2 id="能否指定使用哪个工具" tabindex="-1">能否指定使用哪个工具 <a class="header-anchor" href="#能否指定使用哪个工具" aria-label="Permalink to &quot;能否指定使用哪个工具&quot;">​</a></h2><ul><li>可以在系统提示词里说明，例如： <ul><li>你是一个智能助手，你可以调用 Tavily 搜索工具来获取最新信息。</li><li>如果是关于黄金信息的搜索，你需要调用 Bing 工具。</li><li>如果是关于交通路线的搜索，你需要调用 高德地图 工具。</li></ul></li></ul>',11)])])}const C=i(o,[["render",c]]);export{s as __pageData,C as default};
